def robot_explorer(key):
 return f'''<div class="robot-explorer" data-robot-explorer><div class="interaction-heading"><span class="eyebrow">Choose a setting</span><span class="interaction-hint">Three forms of companionship</span></div><div class="robot-choices" role="group" aria-label="Robot setting"><button type="button" data-robot-choice="outdoor" aria-pressed="true" aria-controls="{key}-scene"><span>01</span> Outdoor</button><button type="button" data-robot-choice="home" aria-pressed="false" aria-controls="{key}-scene"><span>02</span> Home</button><button type="button" data-robot-choice="mini" aria-pressed="false" aria-controls="{key}-scene"><span>03</span> Mini humanoid</button></div><div class="robot-scene" id="{key}-scene"><div class="robot-scene-image"><img data-robot-image src="https://www.zeroth0.com/cdn/shop/files/W1HeroImage.png?v=1766378069&amp;width=1946" alt="Official Zeroth W1 outdoor robot image" width="720" height="500" loading="lazy"><span data-robot-image-note>Official product image / Zeroth</span></div><div class="robot-scene-copy" aria-live="polite" aria-atomic="true"><span class="eyebrow" data-robot-kicker>Outdoor / W1</span><h3 data-robot-title>Take it outside.</h3><p data-robot-description>A tracked platform for carrying equipment, autonomous following, and portable power.</p><dl class="robot-scene-facts"><div><dt data-robot-label-a>Platform</dt><dd data-robot-fact-a>Tracked mobility</dd></div><div><dt data-robot-label-b>Listed capacity</dt><dd data-robot-fact-b>20 kg</dd></div></dl><a class="text-link" data-robot-link href="/projects/robotics/#outdoor">See this version <span aria-hidden="true">↗</span></a></div></div><noscript><p>Explore the <a href="/projects/robotics/#home">home version</a> or <a href="/projects/robotics/#mini">mini humanoid</a>.</p></noscript></div>'''
def upgrade_explorer(key,compact=False):
 return f'''<div class="upgrade-explorer {'upgrade-compact' if compact else ''}" data-upgrade-explorer><div class="interaction-heading"><span class="eyebrow">Try the card mechanism</span><span class="interaction-hint">Drag to change the target tier</span></div><div class="upgrade-scene"><div class="upgrade-inputs" data-upgrade-inputs aria-label="Four lower-tier cards"><span>1★</span><span>1★</span><span>1★</span><span>1★</span></div><span class="upgrade-arrow" aria-hidden="true">→</span><div class="upgrade-card"><span class="upgrade-card-caption">Mechanism model</span><span class="upgrade-stars" data-upgrade-stars aria-label="2 stars">★★</span><strong data-upgrade-tier>Level 2</strong></div></div><div class="upgrade-control"><label for="{key}-tier">Target card tier <output for="{key}-tier" data-upgrade-output>2 / 5</output></label><input id="{key}-tier" type="range" min="1" max="5" step="1" value="2" data-upgrade-range></div><div class="upgrade-readout" aria-live="polite" aria-atomic="true"><p data-upgrade-recipe>Combine 4 Level 1 cards.</p><dl><div><dt>Base-card equivalent</dt><dd data-upgrade-base>4</dd></div><div><dt>Average BTC hashrate units</dt><dd data-upgrade-average>4.83</dd></div></dl><p class="upgrade-calculation" data-upgrade-calculation>4 × 1.05 × 1.15 = 4.83</p></div><p class="interaction-footnote">From the original design table. Normalized BTC hashrate units; not a price or earnings estimate.</p></div>'''
